#!/bin/sh
# Off by default: USB=0 can be generated by the gadget restart itself.
# Users who explicitly opt in still get a lock and a monotonic cooldown.
[ "$(uci -q get gc.config.auto_restart)" = 1 ] || exit 0
ROLE_PATH="/sys/class/udc/ci_hdrc.0/device/driver/ci_hdrc.0/role"
MODE="$(uci get gc.config.mode 2>/dev/null)"

[ "$MODE" = gadget ] && [ "$(uci -q get gc.config.enabled)" = 1 ] || exit 0
grep -q gadget "$ROLE_PATH" 2>/dev/null || exit 0
mkdir /var/run/ufi-gc-restart.lock 2>/dev/null || exit 0
trap 'rmdir /var/run/ufi-gc-restart.lock 2>/dev/null' EXIT
trap 'exit 1' HUP INT TERM
read -r now rest < /proc/uptime
now=${now%%.*}
last=$(cat /var/run/ufi-gc-restart.last 2>/dev/null)
case "$last" in ''|*[!0-9]*) last=0;; esac
[ "$now" -ge 60 ] && [ "$((now - last))" -ge 60 ] || exit 0
printf '%s\n' "$now" > /var/run/ufi-gc-restart.last
logger -t ufi-gc 'USB restart explicitly enabled; rebuilding gadget (60s cooldown)'
/etc/init.d/gc restart
